'use strict';
const liveNames={ufcalendar:'UFCalendar',fighterapi:'FighterAPI',theodds:'The Odds API',unofficial:'Unofficial UFC API',apify:'Apify dataset'};
const liveScope={ufcalendar:'Card details and consensus odds',fighterapi:'Card, matchups and available bookmaker lines',theodds:'Named-book MMA moneylines · US region',unofficial:'Upcoming event data · host availability unconfirmed',apify:'Read up to 100 rows from a completed scraper dataset'};
let evidence=null, refs=[], sourceBout=0, privateStates=null, connectMessage='';
function researchSources(){
 if(!evidence||evidence.event!==data.event.id)return head('Data sources','No matched evidence snapshot is available for this card.','Coverage');
 const e=evidence,f=data.card[sourceBout]||data.card[0],bookList=e.books[cardKey(f)]||[],bench=data.closingTest;
 const tags={wide:'UFC Data · fight and odds archive',judges:'UFC Data · judge-round scores',almanac:'UFC-Almanac · fighter profiles',almanacResults:'UFC-Almanac · fight results',almanacStats:'UFC-Almanac · per-fighter fight stats',daily2:'Kaggle · daily sportsbook observations',master2:'Kaggle · UFC Master',gap:'The Odds Gap · free closing-line sample'};
 const fighterEvidence=[f.a,f.b].map(fighter=>{
  const v=e.fighters[fighter.name]||{},t=v.tape,b=v.bair,m=v.master;
  return '<div class="panel"><h2>'+esc(fighter.name)+'</h2><p class="testcopy">'+(t?'Almanac profile · '+esc(t.Height)+' cm height, '+esc(t.Reach)+' in reach.':'Almanac profile unavailable.')+'</p><p class="testcopy">'+(b?'Last Bair record: '+esc(b.opponent)+' on '+esc(b.date)+'. Rank on preceding board: '+esc(b.rank==null?'unranked':Number(b.rank))+'.':'No matched Bair bout.')+' '+esc(v.judgeRows??0)+' historical judge-round rows.</p><p class="testcopy">'+(m?'Master archive: '+esc(m.opponent)+' · '+esc(m.date)+' · archived moneyline '+esc(m.price||'unavailable')+'. Quote timing unspecified.':'No matching Master record.')+'</p></div>';
 }).join('');
 const benchPanel=bench?'<section class="panel stack"><h2>Against historical closing odds</h2><p class="testcopy">'+bench.model.n.toLocaleString()+' later fights matched on fight ID, date and both fighters, '+day(bench.start)+' through '+day(bench.end)+'. Bair’s margin-adjusted close is an archival market estimate. Lower scores are better.</p><table><tr><th>Forecast</th><th>Accuracy</th><th>Brier</th><th>Log loss</th></tr>'+[['Frozen CL-1',bench.model],['Closing market',bench.market]].map(([l,r])=>'<tr><td>'+l+'</td><td>'+percent(r.accuracy)+'</td><td>'+r.brier.toFixed(3)+'</td><td>'+r.logloss.toFixed(3)+'</td></tr>').join('')+'</table></section>':'';
 const stats=Object.entries(e.sources).map(([k,v])=>'<tr><td><a target="_blank" rel="noreferrer" href="'+safeUrl(v.url)+'">'+esc(tags[k])+'</a></td><td>'+v.count.toLocaleString()+'</td></tr>').join('');
 return head('Data sources','Inspect fighter histories, observed bookmaker prices and closing-line validation.','Cageside Ledger')+'<label class="cap">Matchup <select id="source-bout">'+data.card.map((r,i)=>opt(String(i),short(r.a.name)+' vs '+short(r.b.name),String(sourceBout))).join('')+'</select></label><div class="grid">'+fighterEvidence+'</div><section class="panel stack"><h2>Same-book price snapshots</h2><p class="testcopy">Latest dated observation per sportsbook and region in the daily archive. Decimal odds include the returned stake. These are historical observations.</p><details><summary>'+bookList.length+' book / region records</summary><div class="scroll"><table><tr><th>Sportsbook</th><th>'+esc(short(f.a.name))+'</th><th>'+esc(short(f.b.name))+'</th><th>Observed (ET)</th></tr>'+bookList.map(v=>'<tr><td>'+esc(v.book)+' '+esc(v.region)+'</td><td>'+v.prices[0].toFixed(2)+'</td><td>'+v.prices[1].toFixed(2)+'</td><td>'+esc(when(v.at))+'</td></tr>').join('')+'</table></div></details></section>'+benchPanel+'<div class="panel stack"><h2>Private API connections</h2><p class="testcopy">A successful test saves your key encrypted for later refreshes. Only the signed-in owner can manage these connections. Apify reads an existing dataset.</p><div id="provider-controls">'+providerControls()+'</div><p id="connect-message" role="status">'+esc(connectMessage)+'</p></div><details class="panel stack"><summary>Imported datasets and coverage</summary><table><tr><th>Source</th><th>Rows</th></tr>'+stats+'</table><p class="testcopy">Bair, N. (2026), UFC Data v0.1.1, CC BY 4.0. Derived fields include prior opponent rankings, judging coverage and aligned closing probabilities. UFCStats, MMA Decisions, BestFightOdds and UFCalendar contributed to the original collection.</p><p class="testcopy">The Odds Gap sample includes '+e.gap.length+' book-side opening/closing observations. <a download href="closing-sample.csv">Download the matched-column extract</a>.</p></details><details class="panel stack"><summary>Other supplied sources and model references</summary><p>UFCStats supplies the frozen models through its GitHub mirror. The Aristotle community host returned HTTP 503. The itstimeAPI maintainer marks the hosted service discontinued. The 200-request MMA API listing needs a verified provider endpoint. Tapology pricing and the Zyla directory do not provide an authenticated data feed here.</p><div class="links">'+refs.map(r=>'<a href="https://github.com/'+esc(r.repo)+'" target="_blank" rel="noreferrer">'+esc(r.repo)+'</a>').join('')+'</div></details>';
}
function providerControls(){
 return Object.entries(liveNames).map(([id,label])=>{
  const s=privateStates?.[id];
  return '<details class="journalrow"><summary>'+label+' · '+(s?'connected':privateStates?'needs key':'check connection')+'</summary><p>'+esc(liveScope[id])+'</p><form class="sourceform" data-provider="'+id+'"><label>API key <input type="password" name="token" autocomplete="off" required maxlength="1024"></label> '+(id==='apify'?'<label>Dataset ID <input name="dataset" required></label> ':'')+'<button class="action" type="submit">'+(s?'Replace connection':'Test and connect')+'</button></form>'+(s?'<p>Last successful response: '+esc(when(s.observed))+'</p><button data-refresh-provider="'+id+'">Refresh</button> <button data-remove-provider="'+id+'">Disconnect</button><details><summary>Provider records</summary><pre class="payload">'+esc(JSON.stringify(s.rows,null,2))+'</pre></details>':'')+'</details>';
 }).join('');
}
async function getPrivateStates(){
 try{const r=await fetch('/api/connections',{cache:'no-store'});if(!r.ok)throw Error();privateStates=await r.json();}catch{connectMessage='Sign in as the owner to manage private connections.'}
 const box=document.getElementById('provider-controls');if(box){box.innerHTML=providerControls();document.getElementById('connect-message').textContent=connectMessage}
}
async function changeProvider(id,payload){
 const status=document.getElementById('connect-message');if(status)status.textContent='Contacting '+liveNames[id]+'…';
 try{const r=await fetch('/api/provider/'+id,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await r.json();if(!r.ok)throw Error(result.error||'Provider request failed');connectMessage=liveNames[id]+(payload.action==='disconnect'?' disconnected.':' returned a verified response.');await getPrivateStates()}
 catch(e){connectMessage=e.message;if(status)status.textContent=connectMessage}
}
document.addEventListener('submit',e=>{const form=e.target;if(!form.matches('.sourceform'))return;e.preventDefault();const values=new FormData(form);const payload={action:'connect',key:values.get('token'),dataset:values.get('dataset')};form.reset();changeProvider(form.dataset.provider,payload)});
document.addEventListener('change',e=>{if(e.target.id==='source-bout'){sourceBout=Number(e.target.value);render()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.refreshProvider)changeProvider(b.dataset.refreshProvider,{action:'refresh'});if(b.dataset.removeProvider)changeProvider(b.dataset.removeProvider,{action:'disconnect'});if(b.dataset.tab==='sources')getPrivateStates()});
